// Build safe, fast options. Use localhost and tiny timeouts to avoid long waits.
// Note: Callback variants return an async wrapper type internal to CPR; no persistent handle type is exposed here.
// Construct a minimal, valid option set
cpr::Url url{"http://127.0.0.1"};
// Small timeouts to keep fuzzing snappy
int connect_ms = (int)(*FUZZ_PARAM(unsigned int) % 10) + 1; // 1..10 ms
int total_ms = (int)(*FUZZ_PARAM(unsigned int) % 30) + 1;   // 1..30 ms
cpr::ConnectTimeout cto{connect_ms};
cpr::Timeout to{total_ms};
// Random headers and user-agent to exercise setters
cpr::Header hdr; hdr["X-Fuzz"] = FUZZ_PARAM_STR();
cpr::UserAgent ua{std::string{"fuzz/"} + std::to_string(*FUZZ_PARAM(unsigned int) % 1000)};
// Provide a small body for PATCH
std::string body_str = FUZZ_PARAM_STR();
if (body_str.size() > 1024) { body_str.resize(1024); }
cpr::Body body{body_str};
// Provide a no-op callback that touches the response to cover fields
auto then_cb = [](cpr::Response r){
    volatile long sc = r.status_code; (void)sc;
};
// Invoke target
auto ar = cpr::PatchCallback(then_cb, url, hdr, ua, cto, to, body);
// No outputs to return; async wrapper type is not modeled as a pool object here.
// Validation: Options conform to Session::SetOption-accepted types; tiny timeouts bound runtime.

// Prepare writable file and safe options
const char* out_path = FUZZ_PARAM_FILENAME();
std::ofstream ofs(out_path, std::ios::binary | std::ios::trunc);
if (!ofs.is_open()) { FUZZ_BAIL(); }
// Options: localhost URL and tiny timeouts
cpr::Url url{"http://127.0.0.1"};
int connect_ms = (int)(*FUZZ_PARAM(unsigned int) % 10) + 1; // 1..10 ms
int total_ms = (int)(*FUZZ_PARAM(unsigned int) % 30) + 1;   // 1..30 ms
