// Install an interceptor that delegates to proceed() in a chosen way.
// Avoid using FUZZ_PARAM macros inside the interceptor's methods to prevent codegen issues.
struct FuzzInterceptor final : public cpr::Interceptor {
    explicit FuzzInterceptor(ProceedHttpMethod method, cpr::WriteCallback wcb)
        : method_(method), writecb_(std::move(wcb)) {}

    cpr::Response intercept(cpr::Session& s) override {
        // Dispatch based on the preselected method. For DOWNLOAD, use the provided WriteCallback.
        switch (method_) {
            case ProceedHttpMethod::GET_REQUEST: return proceed(s, ProceedHttpMethod::GET_REQUEST);
            case ProceedHttpMethod::POST_REQUEST: return proceed(s, ProceedHttpMethod::POST_REQUEST);
            case ProceedHttpMethod::PUT_REQUEST: return proceed(s, ProceedHttpMethod::PUT_REQUEST);
            case ProceedHttpMethod::DELETE_REQUEST: return proceed(s, ProceedHttpMethod::DELETE_REQUEST);
            case ProceedHttpMethod::PATCH_REQUEST: return proceed(s, ProceedHttpMethod::PATCH_REQUEST);
            case ProceedHttpMethod::HEAD_REQUEST: return proceed(s, ProceedHttpMethod::HEAD_REQUEST);
            case ProceedHttpMethod::OPTIONS_REQUEST: return proceed(s, ProceedHttpMethod::OPTIONS_REQUEST);
            case ProceedHttpMethod::DOWNLOAD_CALLBACK_REQUEST: return proceed(s, ProceedHttpMethod::DOWNLOAD_CALLBACK_REQUEST, writecb_);
            case ProceedHttpMethod::DOWNLOAD_FILE_REQUEST:
            default:
                // Avoid file I/O in fuzzer; fall back to a simple proceed.
                return proceed(s);
        }
    }

