import random
import string
from typing import List

# Data type: HTTP header value
# Goal: Produce interesting but valid header values (no CR/LF), exercise various semantics
# such as tokens, quoted strings, comma-separated lists, parameters, encodings, long/short, utf-8, etc.

# RFC 7230/7231 header value best practices for fuzz input without breaking syntax:
# - Avoid CR (\r) and LF (\n)
# - Include visible ASCII, spaces, tabs optionally
# - Include quoted-string with escapes
# - Include comma-separated lists and semicolon params
# - Include numbers and quality values (q=)
# - Include UTF-8 non-ASCII sequences
# - Include long values up to a sane cap

_MAX_LEN = 1024  # Keep values small enough for stubs (they also cap to ~1k)

_TOKEN_CHARS = string.ascii_letters + string.digits + "!#$%&'*+-.^_`|~"
_WS = " \t"

def _rand_token(rng: random.Random, min_len=1, max_len=16) -> str:
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(_TOKEN_CHARS) for _ in range(n))

def _rand_quoted_string(rng: random.Random, min_len=0, max_len=40) -> str:
    # quoted-string per RFC: DQUOTE *(qdtext / quoted-pair) DQUOTE
    # We'll avoid CR/LF; allow backslash escapes
    n = rng.randint(min_len, max_len)
    out = '"'
    for _ in range(n):
        ch_type = rng.randint(0, 9)
        if ch_type <= 6:
            # visible ascii excluding DQUOTE and backslash
            c = rng.choice(string.printable[10:94])  # rough range of visibles
            if c in ['"', '\\', '\r', '\n']:
                c = ' '
            out += c
        elif ch_type <= 8:
            # quoted-pair
            c = rng.choice('"\\;,:/= ' + string.ascii_letters + string.digits)
            if c in ['\r', '\n']:
                c = ' '
            out += '\\' + c
        else:
            # UTF-8 multi-byte sample (e.g., non-ASCII)
            out += rng.choice([
                '\u00E9',    # é
                '\u00A9',    # ©
                '\u2603',    # snowman
                '\u2014',    # em dash
            ])
    out += '"'
    return out

def _rand_param(rng: random.Random) -> str:
    # key[=value], where value may be token or quoted
    k = _rand_token(rng, 1, 12)
    if rng.random() < 0.75:
        if rng.random() < 0.6:
            v = _rand_token(rng, 1, 16)
        else:
            v = _rand_quoted_string(rng, 0, 20)
        return f"{k}={v}"
    else:
        return k

def _rand_qvalue(rng: random.Random) -> str:
    # q=0, q=1, or q=0.xyz (0.0-1.0, 3 digits)
    if rng.random() < 0.2:
        return "q=1"
    if rng.random() < 0.2:
        return "q=0"
    frac = rng.randint(0, 999)
    return f"q=0.{frac:03d}"

def _build_accept_like(rng: random.Random) -> str:
    # e.g., text/html;q=0.9;level=1, application/json; charset="utf-8"
    items: List[str] = []
    count = rng.randint(1, 5)
    for _ in range(count):
        type_ = rng.choice(["text", "application", "image", "audio", "video", "*"])
        if type_ == '*':
            value = '*/*'
        else:
            subtype = rng.choice(["plain", "html", "json", "xml", "png", "jpeg", "*"])
            value = f"{type_}/{subtype}"
        params = []
        if rng.random() < 0.8:
            params.append(_rand_qvalue(rng))
        # Some extra parameters
        for _p in range(rng.randint(0, 2)):
            params.append(_rand_param(rng))
        if params:
            value += ';' + ';'.join(params)
        items.append(value)
    # join with comma and optional spaces
    sep = ', '
    return sep.join(items)

def _build_cache_control(rng: random.Random) -> str:
    directives = [
        "no-cache", "no-store", "max-age", "s-maxage", "public", "private",
        "must-revalidate", "proxy-revalidate", "immutable"
    ]
    parts = []
    for _ in range(rng.randint(1, 6)):
        d = rng.choice(directives)
        if d in ("max-age", "s-maxage"):
            parts.append(f"{d}={rng.randint(0, 86400)}")
        else:
            parts.append(d)
    return ', '.join(parts)

def _build_content_disposition(rng: random.Random) -> str:
    disp = rng.choice(["inline", "attachment", "form-data"])
    params = [
        f"filename={_rand_quoted_string(rng, 1, 20)}",
    ]
    if rng.random() < 0.5:
        params.append(f"name={_rand_quoted_string(rng, 1, 12)}")
    return disp + '; ' + '; '.join(params)

