        attrs.append("HttpOnly")
    if rng.random() < 0.5:
        attrs.append("Secure")
    if rng.random() < 0.5:
        attrs.append(f"Max-Age={rng.randint(0, 864000)}")
    if rng.random() < 0.5:
        attrs.append(f"SameSite={rng.choice(['Lax','Strict','None'])}")
    return val_core + ("; " + "; ".join(attrs) if attrs else "")

def _build_auth_value(rng: random.Random) -> str:
    scheme = rng.choice(["Basic", "Bearer", "Digest"])
    if scheme == "Basic":
        # pseudo base64 user:pass but keep ascii
        cred = _rand_token(rng, 6, 24)
        return f"Basic {cred}"
    if scheme == "Bearer":
        token = ''.join(rng.choice(string.ascii_letters + string.digits + '._-') for _ in range(rng.randint(8, 64)))
        return f"Bearer {token}"
    # Digest with some params
    params = [
        f"username={_rand_quoted_string(rng,1,8)}",
        f"realm={_rand_quoted_string(rng,1,8)}",
        f"nonce={_rand_quoted_string(rng,4,12)}",
        f"uri={_rand_quoted_string(rng,1,12)}",
        f"response={_rand_token(rng,8,32)}",
    ]
    return "Digest " + ', '.join(params)

def _build_generic_list(rng: random.Random) -> str:
    # token[, token[;param=...]]*
    items = []
    for _ in range(rng.randint(1, 6)):
        base = _rand_token(rng, 1, 18)
        params = []
        for _p in range(rng.randint(0, 3)):
            params.append(_rand_param(rng))
        if params:
            base += ';' + ';'.join(params)
        items.append(base)
    return ', '.join(items)

def _build_lang_q(rng: random.Random) -> str:
    # Accept-Language style
    langs = []
    for _ in range(rng.randint(1, 5)):
        primary = rng.choice(["en","de","fr","es","zh","ja","ru","ar","pt","it","*"])
        if primary != '*':
            sub = '-' + rng.choice(["US","GB","CN","DE","FR","ES","BR","JP","RU","EG"]) if rng.random()<0.6 else ''
            tag = primary + sub
        else:
            tag = '*'
        params = []
        if rng.random() < 0.8:
            params.append(_rand_qvalue(rng))
        langs.append(tag + (";"+";".join(params) if params else ""))
    return ', '.join(langs)

def _maybe_utf8_tail(rng: random.Random, s: str, max_extra: int = 40) -> str:
    if rng.random() < 0.3:
        extras = rng.randint(1, max_extra)
        tail = ''.join(rng.choice(['\u00E9','\u00F1','\u20AC','\u2603','\u2019']) for _ in range(extras))
        s += tail
    return s

def _sanitize(s: str) -> str:
    # Remove CR/LF to comply with single-line header value expectations
    return s.replace('\r', ' ').replace('\n', ' ')

_BUILDERS = [
    _build_accept_like,
    _build_cache_control,
    _build_content_disposition,
    _build_set_cookie_value,
    _build_auth_value,
    _build_generic_list,
    _build_lang_q,
]

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a strategy mix to produce varied yet valid values
    parts: List[str] = []
    # 1-3 segments combined with commas or simple spaces to simulate complex values
    segs = rng.randint(1, 3)
    for _ in range(segs):
        builder = rng.choice(_BUILDERS)
        seg = builder(rng)
        # Occasionally wrap a segment in quotes to test quoted-string handling where permitted
        if rng.random() < 0.15:
            seg = _rand_quoted_string(rng, 0, 24)
        parts.append(seg)

    # Join with appropriate separators
    sep = rng.choice([', ', ' ', '; ']) if len(parts) > 1 else ''
    value = sep.join(parts)

    # Optional prefix/suffix whitespace
    if rng.random() < 0.5:
        value = rng.choice(['', ' ', '\t']) + value
    if rng.random() < 0.5:
        value = value + rng.choice(['', ' ', '\t'])

    # Optional UTF-8 tail for coverage
    value = _maybe_utf8_tail(rng, value, 10)

    # Ensure within size limits and sanitized
    value = _sanitize(value)
    if len(value) > _MAX_LEN:
        value = value[:_MAX_LEN]

    # Return as bytes (UTF-8 encoding)
    return value.encode('utf-8')

import random
import string
from typing import List

# Target data type: HTTP request body (arbitrary byte string used as payload for POST/PUT/PATCH)
# Used by stubs via FUZZ_PARAM_STR for bodies up to 512/1024/2048 bytes.
# Goal: generate valid, interesting bodies that exercise different code paths while remaining well-formed.

MAX_SIZE = 1024  # keep within typical stub clamps (512..1024), and below 4096

def _rand_ascii(r: random.Random, n: int) -> bytes:
    chars = string.printable.encode('ascii')
    return bytes(r.choices(chars, k=n))

def _json_body(r: random.Random) -> bytes:
    # Small JSON object/array with variability
    keys = [
        "id", "name", "value", "active", "tags", "meta", "count", "items",
        "description", "payload", "data"
    ]
    def rand_key():
        return r.choice(keys)
    def rand_string():
        ln = r.randint(0, 32)
        return ''.join(r.choices(string.ascii_letters + string.digits + ' _-./', k=ln))
    def rand_value(depth=0):
        t = r.randrange(6 if depth < 2 else 4)
        if t == 0:
            return str(r.randint(-2**31, 2**31-1))
        if t == 1:
            return ("true" if r.random() < 0.5 else "false")
        if t == 2:
            return 'null'
        if t == 3:
            return '"' + rand_string().replace('"', '\\"') + '"'
        if t == 4 and depth < 2:
            # array
            m = r.randint(0, 6)
            return '[' + ','.join(rand_value(depth+1) for _ in range(m)) + ']'
        # object
        m = r.randint(0, 6)
        items = []
        used = set()
        for _ in range(m):
            k = rand_key()
            if k in used:
                k = k + '_' + str(r.randint(0, 9))
            used.add(k)
            items.append('"' + k + '"' + ':' + rand_value(depth+1))
        return '{' + ','.join(items) + '}'
    # top may be object or array
    top = rand_value(0)
    return top.encode('utf-8')

def _form_urlencoded(r: random.Random) -> bytes:
    # key=value&key2=value2 with percent-encoding variety
    def pct_encode(s: str) -> str:
        res = []
        for ch in s:
            if ch.isalnum() or ch in '-_.~':
                res.append(ch)
            elif ch == ' ' and r.random() < 0.5:
                res.append('+')
            else:
                res.append('%%%02X' % ord(ch))
        return ''.join(res)
    pairs = []
    n = r.randint(1, 10)
    for _ in range(n):
        klen = r.randint(1, 12)
        vlen = r.randint(0, 24)
        k = ''.join(r.choices(string.ascii_letters + string.digits + ' _-.*', k=klen))
        v = ''.join(r.choices(string.ascii_letters + string.digits + ' _-.*', k=vlen))
        pairs.append(pct_encode(k) + '=' + pct_encode(v))
    return '&'.join(pairs).encode('ascii')

def _xml_body(r: random.Random) -> bytes:
    # Small XML-like payload
    def name():
        start = r.choice(string.ascii_letters)
        rest = ''.join(r.choices(string.ascii_letters + string.digits + '._-', k=r.randint(0, 8)))
        return start + rest
    def text():
        t = ''.join(r.choices(string.ascii_letters + string.digits + ' .,-_/:', k=r.randint(0, 40)))
        t = t.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
        return t
    root = name()
    parts: List[str] = [f'<{root}>']
    for _ in range(r.randint(0, 6)):
        tag = name()
        if r.random() < 0.3:
            # self-closing with attributes
            attrs = []
            for _ in range(r.randint(0, 3)):
                an = name()
                av = text()
                attrs.append(f'{an}="{av}"')
            attr_str = (' ' + ' '.join(attrs)) if attrs else ''
            parts.append(f'<{tag}{attr_str}/>')
        else:
            parts.append(f'<{tag}>' + text() + f'</{tag}>')
    parts.append(f'</{root}>')
    return ''.join(parts).encode('utf-8')

def _multipart_mixed(r: random.Random) -> bytes:
    # Simulate a multipart/form-data-like body without headers context
    boundary = '----fuzz-' + ''.join(r.choices(string.ascii_lowercase + string.digits, k=12))
    lines: List[bytes] = []
    parts = r.randint(1, 4)
    for i in range(parts):
        lines.append(('--' + boundary + '\r\n').encode('ascii'))
        name = 'field' + str(i)
        if r.random() < 0.5:
            filename = 'file' + str(i) + '.bin'
            lines.append(f'Content-Disposition: form-data; name="{name}"; filename="{filename}"\r\n'.encode('ascii'))
            ctype = r.choice(['application/octet-stream','text/plain','application/json'])
            lines.append(f'Content-Type: {ctype}\r\n\r\n'.encode('ascii'))
            # payload
            plen = r.randint(0, 128)
            payload = bytes(r.getrandbits(8) for _ in range(plen))
            lines.append(payload + b"\r\n")
        else:
            lines.append(f'Content-Disposition: form-data; name="{name}"\r\n\r\n'.encode('ascii'))
            sval = ''.join(r.choices(string.ascii_letters + string.digits + ' _-./', k=r.randint(0, 64)))
            lines.append(sval.encode('utf-8') + b"\r\n")
    lines.append(('--' + boundary + '--\r\n').encode('ascii'))
    return b''.join(lines)

def _text_variants(r: random.Random) -> bytes:
    # Plain text variants including repeated patterns and unicode
    choices = []
    # ASCII paragraph
    para = ' '.join(''.join(r.choices(string.ascii_letters + ' ', k=r.randint(1, 8))) for _ in range(r.randint(5, 40)))
    choices.append(para.encode('ascii'))
    # Repeated pattern
    token = ''.join(r.choices('ABCDEFGHIJKLMNOPQRSTUVWXYZ', k=r.randint(1, 4)))
    choices.append((token * r.randint(1, 200)).encode('ascii'))
    # UTF-8 with diverse code points
    unicode_blocks = [
        (0x00A0, 0x00FF),  # Latin-1 Supplement
        (0x0400, 0x04FF),  # Cyrillic
        (0x0370, 0x03FF),  # Greek
        (0x4E00, 0x4EFF),  # CJK subset
        (0x1F300, 0x1F64F) # Emojis
    ]
    def rand_utf8(n):
        out = bytearray()
        for _ in range(n):
            start, end = r.choice(unicode_blocks)
            cp = r.randint(start, end)
            out += chr(cp).encode('utf-8', 'ignore')
        return bytes(out)
    choices.append(rand_utf8(r.randint(1, 100)))
    return r.choice(choices)

def _binary_blob(r: random.Random) -> bytes:
    # Random binary with occasional zero bytes to test Body(const char*, size_t)
    n = r.randint(1, 512)
    blob = bytearray(r.getrandbits(8) for _ in range(n))
    # insert some zeros/newlines
    for _ in range(r.randint(0, 5)):
        if n == 0: break
        idx = r.randrange(n)
        blob[idx] = r.choice([0x00, 0x0A, 0x0D])
    return bytes(blob)

def _sse_stream(r: random.Random) -> bytes:
    # Well-formed SSE events to exercise SSE paths when reused
    lines: List[str] = []
    events = r.randint(1, 5)
    for _ in range(events):
        if r.random() < 0.7:
            lines.append(f"id: {r.randrange(1, 1_000_000)}")
        lines.append("event: message")
        if r.random() < 0.6:
            lines.append(f"retry: {r.randrange(0, 5000)}")
        # multiple data lines
        for _ in range(r.randint(1, 3)):
            data_line = ''.join(r.choices(string.ascii_letters + string.digits + ' _-./', k=r.randint(0, 40)))
            lines.append("data: " + data_line)
        lines.append("")  # blank line terminator
    return ('\n'.join(lines) + '\n').encode('utf-8')

def _compose_mixed(r: random.Random) -> bytes:
    # Compose multiple segments to increase variability while staying under MAX_SIZE
    segments = []
    generators = [_json_body, _form_urlencoded, _xml_body, _text_variants, _binary_blob, _sse_stream]
    r.shuffle(generators)
    for gen in generators:
        if len(b''.join(segments)) > MAX_SIZE * 3 // 4 and r.random() < 0.7:
            break
        seg = gen(r)
        if seg:
            segments.append(seg)
            # delimiter commonly used in HTTP bodies when concatenated
            if r.random() < 0.5:
                segments.append(b"\n")
    out = b''.join(segments)
    return out

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose a body style; weight towards common web payloads
    choice = r.choices(
        population=[
            'json', 'form', 'xml', 'multipart', 'text', 'binary', 'sse', 'mixed'
        ],
        weights=[30, 20, 10, 5, 15, 10, 5, 5], k=1
    )[0]
    if choice == 'json':
        data = _json_body(r)
    elif choice == 'form':
        data = _form_urlencoded(r)
    elif choice == 'xml':
        data = _xml_body(r)
    elif choice == 'multipart':
        data = _multipart_mixed(r)
    elif choice == 'text':
        data = _text_variants(r)
    elif choice == 'binary':
        data = _binary_blob(r)
    elif choice == 'sse':
        data = _sse_stream(r)
    else:
        data = _compose_mixed(r)

    # Ensure non-empty and clamp size to MAX_SIZE
    if not data:
        data = _rand_ascii(r, r.randint(1, 64))
    if len(data) > MAX_SIZE:
        data = data[:MAX_SIZE]
    return data

import random
import string
from typing import List

# This generator targets inputs consumed by FUZZ_PARAM_STR in CPR stubs that expect URL-like strings
# and other HTTP-related strings (headers, proxies, etc.).
# Strategy:
# - Produce a mixture of valid, varied URLs and proxy endpoints.
# - Include different schemes, hosts (IPv4, IPv6, hostnames), ports, paths, queries, and fragments.
# - Keep total size under 4096 bytes.
# - Return as bytes; the fuzzer framework can slice out strings for FUZZ_PARAM_STR and filenames.

SCHEMES = [
    "http", "https", "ftp", "file", "ws", "wss"
]

USER_PWS = [
    ("user", "pass"),
    ("alice", "secret"),
    ("bob", "p@ss:word"),
]

HOSTS = [
    "127.0.0.1",
    "localhost",
    "example.com",
    "sub.domain.test",
]

PATH_SEGMENTS = [
    "", "api", "v1", "resource", "items", "patch", "get", "\u03A9", "%E2%9C%93"
]

QUERY_KEYS = [
    "q", "id", "page", "token", "redirect", "_:weird-key"
]

QUERY_VALUES = [
    "1", "test", "\u00E4\u00F6\u00FC", "true", "false", "A%20B", "../..", ":80"
]

FRAGMENTS = ["", "top", "section-1", "\U0001F60A"]

PROXY_SCHEMES = ["http", "https", "socks5"]

UA_PIECES = ["fuzz", "cpr", "agent", "client", "lib"]


def rand_ipv6(rnd: random.Random) -> str:
    return "[" + ":".join(f"{rnd.randrange(0, 65536):x}" for _ in range(8)) + "]"


def rand_host(rnd: random.Random) -> str:
    pick = rnd.randrange(0, 6)
    if pick == 0:
        return rand_ipv6(rnd)
    if pick == 1:
        return f"{rnd.randrange(1, 255)}.{rnd.randrange(0, 255)}.{rnd.randrange(0, 255)}.{rnd.randrange(1, 255)}"
    if pick == 2:
        return "localhost"
    if pick == 3:
        # simple domain
        labels = ["test", "example", "local", "dev", "foo", "bar"]
        parts = [rnd.choice(labels) for _ in range(rnd.randint(2, 4))]
        return ".".join(parts)
    return rnd.choice(HOSTS)


def rand_port(rnd: random.Random) -> str:
    # include common and edge ports
    choices = ["", "80", "443", "8080", str(rnd.randrange(1, 65535))]
    p = rnd.choice(choices)
    return (":" + p) if p else ""


def rand_userinfo(rnd: random.Random) -> str:
    if rnd.random() < 0.5:
        u, p = rnd.choice(USER_PWS)
        return f"{u}:{p}@"
    return ""


def rand_path(rnd: random.Random) -> str:
    segs = [rnd.choice(PATH_SEGMENTS) for _ in range(rnd.randint(0, 4))]
    # Ensure leading slash for non-empty
    path = "/" + "/".join(s for s in segs if s)
    if rnd.random() < 0.3:
        # add a trailing slash occasionally
        path += "/"
    return path


def rand_query(rnd: random.Random) -> str:
    if rnd.random() < 0.3:
        return ""
    pairs = []
    for _ in range(rnd.randint(1, 4)):
        k = rnd.choice(QUERY_KEYS)
        v = rnd.choice(QUERY_VALUES)
        pairs.append(f"{k}={v}")
    return "?" + "&".join(pairs)


def rand_fragment(rnd: random.Random) -> str:
    frag = rnd.choice(FRAGMENTS)
    return ("#" + frag) if frag else ""


def build_url(rnd: random.Random) -> str:
    scheme = rnd.choice(SCHEMES)
    ui = rand_userinfo(rnd)
    host = rand_host(rnd)
    port = rand_port(rnd)
    path = rand_path(rnd)
    query = rand_query(rnd)
    frag = rand_fragment(rnd)
    return f"{scheme}://{ui}{host}{port}{path}{query}{frag}"


def build_proxy(rnd: random.Random) -> str:
    scheme = rnd.choice(PROXY_SCHEMES)
    host = rand_host(rnd)
    port = rand_port(rnd)
    ui = rand_userinfo(rnd)
    return f"{scheme}://{ui}{host}{port}"


def rand_header_value(rnd: random.Random) -> str:
    # Short printable string, may include tokens
    tokens = [
        "ok", "on", "off", "1", "0", "gzip", "deflate", "br", "keep-alive",
        "max-age=0", "no-cache", "application/json", "text/plain"
    ]
    if rnd.random() < 0.6:
        return rnd.choice(tokens)
    length = rnd.randint(3, 24)
    alphabet = string.ascii_letters + string.digits + "-_.;=/:, "
    return "".join(rnd.choice(alphabet) for _ in range(length)).strip()


def build_user_agent(rnd: random.Random) -> str:
    parts = [rnd.choice(UA_PIECES) + "/" + str(rnd.randint(0, 999)) for _ in range(rnd.randint(1, 3))]
    return " ".join(parts)


def build_body(rnd: random.Random) -> str:
    # Small JSON-ish or plain text body to be valid for PATCH
    if rnd.random() < 0.5:
        # JSON-like
        keys = ["id", "name", "flag", "count", "note"]
        obj = []
        for _ in range(rnd.randint(1, 4)):
            k = rnd.choice(keys)
            if k == "flag":
                v = "true" if rnd.random() < 0.5 else "false"
            elif k == "count":
                v = str(rnd.randint(0, 1000))
            else:
                val = rand_header_value(rnd)
                v = '"' + val.replace('"', '\\"') + '"'
            obj.append(f"\"{k}\": {v}")
        s = "{" + ", ".join(obj) + "}"
        return s[:1024]
    # plain text
    alphabet = string.ascii_letters + string.digits + " \n\t:/._-"
    length = rnd.randint(1, 256)
    return "".join(rnd.choice(alphabet) for _ in range(length))


def assemble_buffer(urls: List[str], proxies: List[str], headers: List[str], uas: List[str], bodies: List[str]) -> bytes:
    # Create a simple newline-delimited corpus. Each line is one candidate string for FUZZ_PARAM_STR.
    lines: List[str] = []
    for u in urls:
        lines.append(u)
    for p in proxies:
        lines.append(p)
    for h in headers:
        lines.append(h)
    for ua in uas:
        lines.append(ua)
    for b in bodies:
        lines.append(b)
    blob = ("\n".join(lines)).encode("utf-8", errors="ignore")
    # Cap size to 4096 bytes
    return blob[:4096]


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    # Build a diverse set of URLs suitable for SetUrl/SetOption and PatchCallback
    urls = [build_url(rnd) for _ in range(rnd.randint(3, 8))]
    # Include some bare hostnames without scheme to exercise prepend logic in stubs
    for _ in range(rnd.randint(1, 3)):
        urls.append(rand_host(rnd) + rand_path(rnd) + rand_query(rnd) + rand_fragment(rnd))
    # Proxies to feed Proxies::Set and related lookups
    proxies = [build_proxy(rnd) for _ in range(rnd.randint(2, 5))]
    # Headers values for X-Fuzz etc.
    headers = [rand_header_value(rnd) for _ in range(rnd.randint(3, 6))]
    # User-Agents
    uas = [build_user_agent(rnd) for _ in range(rnd.randint(2, 4))]
    # Bodies for PATCH
    bodies = [build_body(rnd) for _ in range(rnd.randint(2, 5))]
    return assemble_buffer(urls, proxies, headers, uas, bodies)

import random
import string
from typing import List

# Data type: username string
# Goal: Produce interesting but valid usernames for HTTP authentication contexts.
# These will seed FUZZ_PARAM_STR in stubs constructing Authentication and ProxyAuthentication.
# Constraints observed in stubs:
# - Username strings may be truncated to 32 or 64 chars depending on call site.
# Strategy:
# - Generate a variety of realistic usernames:
#   * Simple alnum, emails, domain\\user (NTLM), UTF-8 with emojis/accents, mixed punctuation allowed in URLs.
#   * Include edge cases: empty string, single char, max-length boundaries (32/64), leading/trailing spaces, percent-encoded content.
# - Keep total buffer under 4096 bytes by choosing one username per generate() call with some randomness, plus occasionally composing with separators.
# - Return as bytes encoded in UTF-8.

COMMON_LOCAL_PARTS = [
    "user", "admin", "test", "guest", "root", "service", "api", "bot", "dev", "qa",
    "john", "jane", "alice", "bob", "charlie", "eve",
]
COMMON_DOMAINS = [
    "example.com", "test.local", "intranet", "corp.local", "domain.tld",
    "example.org", "example.net", "localhost",
]
UNICODE_USER_FRAGMENTS = [
    "jörg", "marié", "Анна", "用户", "テスト", "اختبار", "παύλος", "ñandú", "søren", "Łukasz",
    "😀user", "用户123", "δοκιμή",
]
SAFE_PUNCT = "._-+"  # common allowed username punctuation
URL_PCT = ["%20", "%2F", "%3A", "%40", "%21", "%2B", "%25"]


def _rand(rng: random.Random, seq: List[str]):
    return rng.choice(seq)


def _rand_alnum(rng: random.Random, min_len: int, max_len: int):
    length = rng.randint(min_len, max_len)
    alphabet = string.ascii_letters + string.digits
    return ''.join(rng.choices(alphabet, k=length))


def _maybe(rng: random.Random, p: float):
    return rng.random() < p


def _email_username(rng: random.Random):
    # Construct email-like username
    local = _rand(rng, COMMON_LOCAL_PARTS)
    # sprinkle digits/punct
    if _maybe(rng, 0.6):
        local += rng.choice(SAFE_PUNCT)
        local += str(rng.randint(0, 9999))
    domain = _rand(rng, COMMON_DOMAINS)
    return f"{local}@{domain}"


def _ntlm_username(rng: random.Random):
    # DOMAIN\\user style
    domain = _rand_alnum(rng, 3, 10).upper()
    user = _rand_alnum(rng, 3, 12).lower()
    return f"{domain}\\\\{user}"


def _unicode_username(rng: random.Random):
    base = _rand(rng, UNICODE_USER_FRAGMENTS)
    if _maybe(rng, 0.5):
        base += rng.choice(SAFE_PUNCT)
    if _maybe(rng, 0.4):
        base += str(rng.randint(1, 999))
    return base


def _percent_encoded(rng: random.Random):
    # Mix alnum with percent-encoded sequences
    parts = []
    for _ in range(rng.randint(2, 6)):
        if _maybe(rng, 0.5):
            parts.append(_rand_alnum(rng, 1, 4))
        else:
            parts.append(_rand(rng, URL_PCT))
    return ''.join(parts)


def _padded_edges(rng: random.Random, s: str):
    # Sometimes add leading/trailing spaces or tabs
    if _maybe(rng, 0.25):
        s = (" " * rng.randint(1, 2)) + s
    if _maybe(rng, 0.25):
        s = s + ("\t" if _maybe(rng, 0.5) else " ")
    return s


def _bounded(rng: random.Random, s: str):
    # Target typical truncation sizes: 32 or 64
    target = rng.choice([16, 24, 31, 32, 40, 63, 64])
    if len(s) < target and _maybe(rng, 0.5):
        # Extend with safe characters
        pad = ''.join(rng.choices(string.ascii_lowercase + SAFE_PUNCT, k=target - len(s)))
        s = s + pad
    return s[:target]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    choice = rng.randint(0,  nine := 9)
    if choice == 0:
        s = ""  # empty username
    elif choice == 1:
        s = _rand_alnum(rng, 1, 2)  # very short
    elif choice == 2:
        s = _email_username(rng)
    elif choice == 3:
        s = _ntlm_username(rng)
    elif choice == 4:
        s = _unicode_username(rng)
    elif choice == 5:
        s = _percent_encoded(rng)
    elif choice == 6:
        # Mixed style: email local part with unicode
        s = _rand(rng, UNICODE_USER_FRAGMENTS) + "+" + _rand(rng, COMMON_LOCAL_PARTS)
    elif choice == 7:
        # Alnum with punctuation, maximum-bound
        s = _bounded(rng, _rand_alnum(rng, 8, 20) + rng.choice(SAFE_PUNCT) + _rand_alnum(rng, 4, 12))
    else:
        # Composite with separators common in usernames
        sep = rng.choice([".", "_", "-", "+"]) 
        s = _rand(rng, COMMON_LOCAL_PARTS) + sep + _rand_alnum(rng, 3, 10)

    s = _padded_edges(rng, s)
    s = _bounded(rng, s)

    # Ensure <= 4096 bytes (guaranteed by bound)
    return s.encode('utf-8')

import random
import ipaddress
from typing import List

# Target data type: IP address string (IPv4 or IPv6).
# Fuzzer stubs use FUZZ_PARAM_STR for host and addr. Our bytes will be consumed
# as a string source; we therefore return a UTF-8 text buffer containing multiple
# newline-separated tokens that the fuzzing harness can slice to supply
# FUZZ_PARAM_STR calls. We aim to provide valid and interesting IP strings.

SPECIAL_IPV4 = [
    "0.0.0.0",
    "127.0.0.1",
    "255.255.255.255",
    "224.0.0.1",   # multicast
    "169.254.0.1", # link-local
    "192.0.2.1",   # TEST-NET-1
    "198.51.100.2",# TEST-NET-2
    "203.0.113.3", # TEST-NET-3
]

SPECIAL_IPV6 = [
    "::",
    "::1",
    "::ffff:127.0.0.1",
    "2001:db8::1",     # documentation prefix
    "fe80::1",         # link-local
    "ff02::1",         # multicast all-nodes
    "2001:4860:4860::8888", # public resolver
]

HOST_EXAMPLES = [
    "example.test",
    "a.test",
    "b.test",
    "xn--bcher-kva.example",   # IDNA-like label
    "sub.domain.test",
    "local",
]

def rand_ipv4(rng: random.Random) -> str:
    # Weight toward private, loopback, edge cases
    choice = rng.randint(0, 9)
    if choice < 4:
        return f"192.168.{rng.randint(0,255)}.{rng.randint(0,255)}"
    if choice < 6:
        return f"10.{rng.randint(0,255)}.{rng.randint(0,255)}.{rng.randint(0,255)}"
    if choice == 6:
        return f"172.{rng.randint(16,31)}.{rng.randint(0,255)}.{rng.randint(0,255)}"
    if choice == 7:
        return "127.0." + str(rng.randint(0,255)) + "." + str(rng.randint(1,254))
    if choice == 8:
        return rng.choice(SPECIAL_IPV4)
    # fully random
    return f"{rng.randint(0,255)}.{rng.randint(0,255)}.{rng.randint(0,255)}.{rng.randint(0,255)}"


def rand_ipv6(rng: random.Random) -> str:
    # Generate via ipaddress to ensure validity; random 128-bit
    val = rng.getrandbits(128)
    ip = ipaddress.IPv6Address(val)
    # Occasionally pick from specials
    if rng.random() < 0.4:
        return rng.choice(SPECIAL_IPV6)
    # Sometimes embed IPv4-mapped
    if rng.random() < 0.2:
        v4 = rand_ipv4(rng)
        try:
            ip_mapped = ipaddress.IPv6Address("::ffff:" + v4)
            return str(ip_mapped)
        except Exception:
            pass
    # Compress or expand by str() default (compressed)
    return str(ip)


def rand_host(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return rng.choice(HOST_EXAMPLES)
    # Build a plausible hostname label set
    def label() -> str:
        L = rng.randint(1, 20)
        s = []
        for i in range(L):
            chset = "abcdefghijklmnopqrstuvwxyz0123456789-"
            c = rng.choice(chset)
            s.append(c)
        # Ensure no leading/trailing dash
        if s[0] == '-':
            s[0] = 'a'
        if s[-1] == '-':
            s[-1] = 'z'
        return "".join(s)
    labels = [label() for _ in range(rng.randint(2, 4))]
    tld = rng.choice(["test", "example", "invalid", "local", "com", "net"])
    return ".".join(labels + [tld])


def make_token_set(rng: random.Random) -> List[str]:
    tokens: List[str] = []
    # Provide a mix of hosts and IPs because the stubs call FUZZ_PARAM_STR multiple times
    # and apply defaults if empty. Keep token sizes within stub caps (<=128 for host, <=64 for addr).

    # A couple of hosts
    for _ in range(3):
        tokens.append(rand_host(rng)[:128])

    # IPv4-heavy set
    for _ in range(4):
        tokens.append(rand_ipv4(rng)[:64])

    # IPv6-heavy set
    for _ in range(4):
        tokens.append(rand_ipv6(rng)[:64])

    # Edge ports hints not used directly here, but include additional tokens to increase diversity
    tokens += [
        "127.1",
        "0.0.0.0",
        "::ffff:0:0",
        "fe80::dead:beef",
    ]

    # Shuffle to vary consumption order
    rng.shuffle(tokens)
    return tokens


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    tokens = make_token_set(rng)

    # Join as newline-separated UTF-8 text so each FUZZ_PARAM_STR() can read a distinct slice.
    # Keep under 4096 bytes.
    text = "\n".join(tokens)
    if len(text) > 4096:
        text = text[:4096]
    return text.encode("utf-8")
